    $("iwDocumentHead").innerHTML=`<tr>${(kind==="receipts"?["分类","品名","单位","入库数量","单价（元）","金额（元）",""]:kind==="issues"?["品项 / 可用库存","出库数量","单位","FIFO 成本",""]:["品项","账面库存","实盘数量","盘盈单价（选填）","差异",""]).map(text=>`<th>${text}</th>`).join("")}</tr>`;
