    const choice=`<select data-iw-field="stockKey" data-testid="inventory-line-item" aria-label="选择库存品项"><option value="">选择品项</option>${ui.data.balances.filter(row=>kind==="counts"||row.remaining>EPS).map(row=>`<option value="${encoded(row)}" ${line.stockKey===identity(row)?"selected":""}>${esc(row.name)} · ${esc(row.unit)}（${esc(row.category)}，可用 ${qty(row.remaining)}）</option>`).join("")}</select>`;
