      if(modal.kind==="counts"){
        if(counted.has(line.stockKey))throw new Error("同一品项在盘点单中只能填写一行。");counted.add(line.stockKey);
        const price=entered(line.price)?Exact.decimal(Exact.price(inputNumber(line.price,`${label}盘盈单价`,true))):null,difference=quantity-stock.remaining;
        lines.push({...line,...itemIdentity(stock),quantity,previous_quantity:stock.remaining,unit_price:price,price_known:price!==null});previews.push({difference,cost:difference>0&&price!==null?difference*price:0,unknownQuantity:difference>0&&price===null?difference:0,allocations:[]});continue;
      }
