    try{const data=snapshot(),{lines}=validateDocument(modal,data),payload=clone(data.payload),recorded_at=timestamp(payload),array={receipts:"entries",issues:"adjustments",counts:"overrides"}[modal.kind];
      for(const line of lines){const row={id:line.id,date:modal.date,...itemIdentity(line),quantity:line.quantity,document_id:modal.id,document_no:modal.no,recorded_at,note:modal.note.trim(),voided:false};if(modal.kind==="receipts")Object.assign(row,{unit_price:line.unit_price,total:line.total,price_known:true,source:"manual"});else if(modal.kind==="issues")row.kind=modal.issueKind;else Object.assign(row,{previous_quantity:line.previous_quantity,unit_price:line.unit_price,price_known:line.price_known});payload[array].push(row);}
      await commit(payload,modal);modal.dirty=false;closeModal(true);setTab(modal.kind);$("iwNotice").hidden=false;$("iwNotice").textContent=`${modal.no} 已保存，共 ${lines.length} 行。`;
    }catch(error){modalError(error);button.disabled=false;button.textContent="确认保存";}
