    let changed=0;payload[array]=payload[array].map((raw,index)=>{const id=String(raw.id||`${array==="entries"?"manual":"adjustment"}:${index}`);if(!wanted.has(id))return raw;changed++;return {...raw,voided:true,void_reason:reason,voided_at:new Date().toISOString()};});
    if(!changed)throw new Error("未找到原单据，可能已被其他设备更新。请刷新后重试。");const before=snapshot(),after=snapshot(payload),shortages=shortageIncrease(before,after);return {payload,before,after,shortages};
