    const host=createModal(`作废 ${doc.document_no}`,"单据保留，可追溯原因；不直接删除记录。",body,`<button type="button" class="iw-button" data-iw-close>取消</button><span class="iw-spacer"></span><button type="button" class="iw-button iw-danger" id="iwVoidSubmit" data-testid="inventory-void-submit" ${candidate.shortages.length?"disabled":""}>确认作废</button>`);ui.modal={type:"void",dataset:state.dataset.id,version:activeVersion(),dirty:false};const modal=ui.modal;
    $("iwVoidReason").addEventListener("input",()=>modal.dirty=true);$("iwVoidSubmit").addEventListener("click",async event=>{const button=event.target;button.disabled=true;try{const reason=$("iwVoidReason").value.trim();if(!reason)throw new Error("请填写作废原因。");const next=voidCandidate(doc,reason);if(next.shortages.length)throw new Error("当前库存已变化，作废会产生新的库存短缺，未提交。");await commit(next.payload,modal);modal.dirty=false;closeModal(true);render();}catch(error){modalError(error);button.disabled=false;}});
