        const result=await api(`/datasets/${encodeURIComponent(modal.dataset)}/inventory/name-corrections/apply`,{method:'POST',body:JSON.stringify({...modal.previewValues,preview_token:modal.preview.preview_token,reason,request_id:modal.requestId,confirm_merge:Boolean($('iwCorrectionMerge')?.checked)})});
        if(!result?.applied)throw new Error(result?.message||'服务器未确认更正，请重新预览。');modal.dirty=false;modal.applied=true;$('iwCorrectionPreview').disabled=true;
        try{const waitStart=Date.now();while(state.refreshBusy){if(Date.now()-waitStart>30000)throw new Error('等待云端刷新超时');await new Promise(resolve=>setTimeout(resolve,100));}await loadCloudData();closeModal(true);ui.tab='stock';ui.page=1;ui.category='';ui.status='';ui.from='';ui.to='';ui.query=modal.previewValues.new_name;$('iwSearch').value=ui.query;render();$('iwNotice').hidden=false;$('iwNotice').textContent=result.message||'品名已统一更正，关联记录已重新加载。';}
        catch(error){button.textContent='已更正';modalError(new Error('更正已成功，但重新加载失败。请关闭窗口后点击刷新，勿重复提交。'+(error.message||'')));}
